(()=>{'use strict';
const CakeI18n=globalThis.CakeI18n||(typeof require==='function'?require('./i18n.js'):null),T=CakeI18n.t;

const C=CakeCore,{D}=C,$=s=>document.querySelector(s),app=$('#app'),store=new CakeStore();
let db=C.emptyDB(),engine,route='materials',selected=null,draft=null,invalid=false,query='',categoryFilter='',limit=50,storageFailed=false,ready=false;
CakeI18n.hydrate();
const routes=CakeI18n.routes;
// Product-facing copy for the overview and sharing flows. Existing domain labels
// continue to use the audited catalog-backed T() helper.
const featureCopy={
 en:{overview:'Overview',overviewSubtitle:'A calm starting point for every calculation.',quickActions:'Quick actions',newMaterial:'New material',newRecipe:'New recipe',newProduct:'New product',loadDemo:'Open demo workspace',materials:'Materials',recipes:'Recipes',products:'Products',welcomeTitle:'Build your first calculation in minutes',welcomeBody:'Start with a demo workspace or add your first ingredient. Everything stays in this browser.',stepOne:'1. Add materials',stepTwo:'2. Build a recipe',stepThree:'3. Set your selling price',sharePdf:'Share PDF',shoppingList:'Shopping list',scenarioTitle:'Price scenarios',scenarioHint:'Compare common selling-price strategies without changing the saved calculation.',current:'Current',recent:'Recent work',templates:'Template library',templatesBody:'Use the demo as a starting point, or duplicate any recipe and product as an independent template.',openMaterials:'Open materials',openRecipes:'Open recipes',openProducts:'Open product builder',shared:'Share sheet opened.',sharedFallback:'Sharing is unavailable here; the PDF was downloaded instead.',packages:'packages',nothingYet:'Nothing saved yet',nothingYetBody:'Your first material becomes the foundation for every recipe and product.'},
 ru:{overview:'Обзор',overviewSubtitle:'Спокойная стартовая точка для каждого расчёта.',quickActions:'Быстрые действия',newMaterial:'Новый материал',newRecipe:'Новый рецепт',newProduct:'Новое изделие',loadDemo:'Открыть демо-рабочее пространство',materials:'Материалы',recipes:'Рецепты',products:'Изделия',welcomeTitle:'Соберите первый расчёт за несколько минут',welcomeBody:'Начните с демо или добавьте первый ингредиент. Всё остаётся в этом браузере.',stepOne:'1. Добавьте материалы',stepTwo:'2. Соберите рецепт',stepThree:'3. Настройте цену продажи',sharePdf:'Поделиться PDF',shoppingList:'Список закупки',scenarioTitle:'Сценарии цены',scenarioHint:'Сравните варианты цены, не меняя сохранённую калькуляцию.',current:'Текущий',recent:'Последние работы',templates:'Библиотека шаблонов',templatesBody:'Используйте демо как основу или дублируйте любой рецепт и продукт как независимый шаблон.',openMaterials:'Открыть материалы',openRecipes:'Открыть рецепты',openProducts:'Открыть конструктор',shared:'Открыто меню «Поделиться».',sharedFallback:'Здесь нельзя поделиться напрямую — PDF скачан вместо этого.',packages:'упаковок',nothingYet:'Пока ничего нет',nothingYetBody:'Первый материал станет основой каждого рецепта и изделия.'}
};
function F(key){return(featureCopy[CakeI18n.language]||featureCopy.en)[key]||featureCopy.en[key]||key;}

// Collapsible mobile navigation; desktop navigation remains permanently visible.
function setMenu(open){$('#menu-toggle').setAttribute('aria-expanded',String(open));$('.sidebar').classList.toggle('menu-open',open);}
$('#menu-toggle').addEventListener('click',()=>setMenu($('#menu-toggle').getAttribute('aria-expanded')!=='true'));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.sidebar').classList.contains('menu-open')){setMenu(false);$('#menu-toggle').focus();}});
document.addEventListener('click',e=>{if(!e.target.closest('.sidebar'))setMenu(false);});
// Browser-independent, offline calendar. Intl supplies language-specific months/weekdays/digits.
let calendarInput=null,calendarMonth=null;
const calendar=document.createElement('dialog');calendar.className='calendar-dialog';calendar.setAttribute('aria-label',T('Календарь'));document.body.append(calendar);
const isoDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function paintCalendar(focusDate){
 const locale=CakeI18n.languages[CakeI18n.language].locale,y=calendarMonth.getFullYear(),m=calendarMonth.getMonth();
 const fmt=opts=>new Intl.DateTimeFormat(locale,opts),first=new Date(y,m,1),offset=(first.getDay()+6)%7,count=new Date(y,m+1,0).getDate(),selected=calendarInput.value;
 calendar.innerHTML=`<div class="calendar-head"><button class="icon-button" data-month="-1" aria-label="${esc(T('Предыдущий месяц'))}">‹</button><strong aria-live="polite">${esc(fmt({month:'long',year:'numeric'}).format(first))}</strong><button class="icon-button" data-month="1" aria-label="${esc(T('Следующий месяц'))}">›</button></div><div class="calendar-grid">${Array.from({length:7},(_,i)=>`<span class="weekday">${esc(fmt({weekday:'short'}).format(new Date(2024,0,1+i)))}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const day=new Date(y,m,i+1),iso=isoDate(day);return `<button class="calendar-day" data-date="${iso}" aria-label="${esc(fmt({dateStyle:'full'}).format(day))}" aria-pressed="${iso===selected}" ${iso===isoDate(new Date())?'aria-current="date"':''}>${esc(new Intl.NumberFormat(locale).format(i+1))}</button>`;}).join('')}</div><button class="button secondary full" data-close-calendar>${esc(T('Закрыть календарь'))}</button>`;
 if(focusDate)calendar.querySelector(`[data-date="${focusDate}"]`)?.focus();
}
document.addEventListener('click',e=>{const button=e.target.closest('[data-calendar]');if(!button)return;calendarInput=app.querySelector(`[data-field="${button.dataset.calendar}"]`);const parsed=new Date(calendarInput.value+'T12:00:00');calendarMonth=Number.isNaN(parsed.getTime())?new Date():parsed;paintCalendar();calendar.showModal();(calendar.querySelector('[aria-pressed="true"]')||calendar.querySelector('[data-date]')).focus();});
calendar.addEventListener('click',e=>{const month=e.target.closest('[data-month]');if(month){calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+Number(month.dataset.month),1);const dir=month.dataset.month;paintCalendar();calendar.querySelector(`[data-month="${dir}"]`).focus();return;}const day=e.target.closest('[data-date]');if(day){calendarInput.value=day.dataset.date;calendarInput.dispatchEvent(new Event('input',{bubbles:true}));calendar.close();calendarInput.focus();}if(e.target.closest('[data-close-calendar]'))calendar.close();});
calendar.addEventListener('keydown',e=>{const current=e.target.closest('[data-date]');if(!current)return;const delta={ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7}[e.key];if(delta===undefined)return;e.preventDefault();const d=new Date(current.dataset.date+'T12:00:00');d.setDate(d.getDate()+delta);calendarMonth=d;paintCalendar(isoDate(d));});

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=o=>JSON.parse(JSON.stringify(o));
// Language is a small interface preference, not an edit of recipe data or currency.
$('#language-select').addEventListener('change',async event=>{const next=event.target.value;if(!leaveDraft()||!confirm(T('Переключить язык и перезагрузить страницу? Допустимые изменения будут сохранены.'))){event.target.value=CakeI18n.language;return;}try{await store.flush();localStorage.setItem(CakeI18n.key,next);location.reload();}catch{event.target.value=CakeI18n.language;globalError(T('Не удалось сохранить данные. Сначала скачайте JSON-копию; язык пока не изменён.'));}});
function money(v){return v===null?'—':new Intl.NumberFormat(db.settings.locale,{style:'currency',currency:db.settings.currency,minimumFractionDigits:2,maximumFractionDigits:2}).format(D(v).round(2).toString());}
function number(v,digits=3){return v===null?'—':new Intl.NumberFormat(db.settings.locale,{maximumFractionDigits:digits}).format(D(v).toNumber());}
const unit=u=>C.UNITS[u]?.label||u;
const tableName=()=>route==='materials'?'materials':route==='recipes'?'recipes':'products';
const entities=()=>db[tableName()];
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,6000);}
function globalError(s){$('#global-message').textContent=s;$('#global-message').hidden=!s;}
async function download(blob,name){
 try{try{await store.flush();}catch{} // Exports remain available even after a storage failure.
 const trigger=url=>{const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();};
 if(location.protocol==='file:'&&blob.type==='application/pdf'){const reader=new FileReader();reader.onload=()=>trigger(reader.result);reader.onerror=()=>globalError(T("Не удалось подготовить PDF к скачиванию."));reader.readAsDataURL(blob);}
 else{const url=URL.createObjectURL(blob);trigger(url);setTimeout(()=>URL.revokeObjectURL(url),30000);}
 }catch(e){globalError(T("Не удалось скачать файл: ")+e.message);}
}
function backup(silent=false){if(!ready)return;if(invalid&&!silent)toast(T("В копию входят последние допустимые значения. Некорректный черновик не сохраняется."));db.exportedAt=new Date().toISOString();if(!storageFailed)store.save(db);download(new Blob([JSON.stringify(db,null,2)],{type:'application/json;charset=utf-8'}),`CakeCalc-backup-${new Date().toISOString().slice(0,10)}.json`);updateBackupNote();}
function updateBackupNote(){$('#backup-note').textContent=db.exportedAt?T("Последняя выгрузка: ")+new Date(db.exportedAt).toLocaleString(db.settings.locale):T("Копий ещё нет. Очистка браузера удалит вашу базу.");}
store.onstatus=(kind,text)=>{const el=$('#save-status');el.textContent=text;el.className=kind==='error'?'error-text':'';};
store.onfailure=()=>{storageFailed=true;globalError(T("Не удалось сохранить данные. Работа остаётся в памяти этой вкладки. Скачайте JSON-копию до закрытия страницы. При конфликте вкладок перезагрузите страницу после экспорта."));};
store.onexternal=()=>{if(!store.busy&&!store.pending)globalError(T("База изменилась в другой вкладке. Чтобы не перезаписать чужие изменения, сохраните свой JSON и перезагрузите эту страницу."));};
function persist(){if(!storageFailed)store.save(db);updateBackupNote();}
function options(values,current){return values.map(([value,label])=>`<option value="${esc(value)}" ${String(current)===String(value)?'selected':''}>${esc(label)}</option>`).join('');}
function dateField(label,path,value){return `<div class="date-control"><div class="date-field"><label>${esc(label)}<input data-field="${esc(path)}" value="${esc(value)}" type="text" inputmode="numeric" placeholder="YYYY-MM-DD" maxlength="10" autocomplete="off"></label><button type="button" class="button secondary" data-calendar="${esc(path)}" aria-label="${esc(T('Календарь'))}">▦</button></div></div>`;}
function field(label,path,value,{type='text',hint='',wide=false,decimal=false}={}){if(type==='date')return dateField(label,path,value);return`<label class="${wide?'wide':''}">${esc(label)}${type==='textarea'?`<textarea data-field="${esc(path)}">${esc(value)}</textarea>`:`<input data-field="${esc(path)}" value="${esc(value)}" type="${type}" ${decimal?'inputmode="decimal" autocomplete="off"':''}>`}${hint?`<small>${esc(hint)}</small>`:''}</label>`;}
function select(label,path,value,values,hint=''){return`<label>${esc(label)}<select data-field="${esc(path)}">${options(values,value)}</select>${hint?`<small>${esc(hint)}</small>`:''}</label>`;}
function check(label,path,checked){return`<label class="check"><input type="checkbox" data-field="${esc(path)}" ${checked?'checked':''}>${esc(label)}</label>`;}
function metric(label,value,sub='',primary=false){return`<div class="metric${primary?' primary':''}"><span>${esc(label)}</span><strong>${esc(value)}</strong>${sub?`<small>${esc(sub)}</small>`:''}</div>`;}
function setPath(obj,path,value){const parts=path.split('.');if(parts.some(k=>['__proto__','constructor','prototype'].includes(k)))throw Error(T("Недопустимое поле."));let cursor=obj;for(const part of parts.slice(0,-1))cursor=cursor[part];cursor[parts.at(-1)]=value;}
function getPath(obj,path){return path.split('.').reduce((o,k)=>o[k],obj);}
function acceptDraft({render=false}={}){
 try{const key=tableName(),candidate={...db,[key]:db[key].map(row=>row.id===selected?clone(draft):row)},next=new C.Engine(candidate);db=candidate;engine=next;invalid=false;const title=$('.detail-header h2');if(title)title.textContent=draft.name;const dimension=$('#tier-dimension');if(dimension&&draft.cake)dimension.textContent=(draft.cake.shape==='round'?T("Диаметр"):T("Сторона"))+T(", см");const error=$('#edit-error');if(error){error.hidden=true;error.textContent='';}persist();renderList();if(render)renderDetail();else updateLive();return true;}
 catch(e){invalid=true;const error=$('#edit-error');if(error){error.textContent=e.message+T(" Показан последний допустимый расчёт; изменение пока не сохранено.");error.hidden=false;}return false;}
}
function leaveDraft(){return!invalid||confirm(T("В черновике есть некорректные значения, которые не сохранены. Перейти и отбросить их?"));}
function navigate(next){if(!routes[next]||!leaveDraft())return;setMenu(false);route=next;selected=null;draft=null;invalid=false;query='';categoryFilter='';limit=50;location.hash=next;render();window.scrollTo(0,0);}
function firstRun(){try{return !localStorage.getItem('argoncakecalc-onboarding-seen')&&!db.materials.length&&!db.recipes.length&&!db.products.length;}catch{return false;}}
function markFirstRun(){try{localStorage.setItem('argoncakecalc-onboarding-seen','1');}catch{}}
function onboardingCard(){if(!firstRun())return '';return `<section class="welcome-card"><div class="welcome-mark" aria-hidden="true">✦</div><div class="welcome-copy"><span class="eyebrow">${esc(F('overview'))}</span><h2>${esc(F('welcomeTitle'))}</h2><p>${esc(F('welcomeBody'))}</p><div class="welcome-steps"><span>${esc(F('stepOne'))}</span><span>${esc(F('stepTwo'))}</span><span>${esc(F('stepThree'))}</span></div><div class="actions"><button class="button" data-action="new">${esc(F('newMaterial'))}</button><button class="button secondary" data-action="demo">${esc(F('loadDemo'))}</button></div></div></section>`;}
function renderDashboard(){
 const counts=[['materials',db.materials.length,F('materials')],['recipes',db.recipes.length,F('recipes')],['products',db.products.length,F('products')]];
 const recent=[...db.products.slice(0,3).map(x=>({...x,_type:F('products'),_route:'products'})),...db.recipes.slice(0,2).map(x=>({...x,_type:F('recipes'),_route:'recipes'})),...db.materials.slice(0,2).map(x=>({...x,_type:F('materials'),_route:'materials'}))].slice(0,5);
 const product=db.products[0];let productCard='';
 if(product){try{const r=engine.product(product.id);productCard=`<section class="card spotlight"><div><span class="badge">${esc(F('current'))}</span><h2>${esc(product.name)}</h2><p class="subtle">${esc(F('products'))} · ${esc(F('recent'))}</p></div><div class="spotlight-price"><span>${esc(F('scenarioTitle'))}</span><strong>${esc(money(r.sale))}</strong><small>${esc(T('Себестоимость'))}: ${esc(money(r.full))}</small></div><button class="button" data-route="products">${esc(F('openProducts'))}</button></section>`;}catch{}}
 app.innerHTML=`<section class="dashboard-hero"><div><span class="eyebrow">${esc(F('overview'))}</span><h2>${esc(F('overviewSubtitle'))}</h2><p class="subtle">${esc(F('nothingYetBody'))}</p></div><div class="actions"><button class="button" data-action="new-material">${esc(F('newMaterial'))}</button><button class="button secondary" data-action="demo">${esc(F('loadDemo'))}</button></div></section><section class="dashboard-grid metrics-grid">${counts.map(([key,count,label])=>`<button class="metric-card" data-route="${key}"><span>${esc(label)}</span><strong>${count}</strong><small>${esc(key==='materials'?F('openMaterials'):key==='recipes'?F('openRecipes'):F('openProducts'))} →</small></button>`).join('')}</section>${productCard}<div class="dashboard-columns"><section class="card"><div class="section-title"><h2>${esc(F('quickActions'))}</h2></div><div class="quick-actions"><button class="quick-action" data-action="new-material"><strong>${esc(F('newMaterial'))}</strong><span>＋</span></button><button class="quick-action" data-action="new-recipe"><strong>${esc(F('newRecipe'))}</strong><span>＋</span></button><button class="quick-action" data-action="new-product"><strong>${esc(F('newProduct'))}</strong><span>＋</span></button></div></section><section class="card"><div class="section-title"><h2>${esc(F('templates'))}</h2></div><p class="subtle">${esc(F('templatesBody'))}</p><button class="button secondary" data-action="demo">${esc(F('loadDemo'))}</button></section></div><section class="card recent-card"><div class="section-title"><h2>${esc(F('recent'))}</h2><button class="link" data-route="materials">${esc(F('openMaterials'))}</button></div>${recent.length?`<div class="recent-list">${recent.map(x=>`<button class="recent-item" data-route="${x._route}"><span class="recent-dot" aria-hidden="true"></span><span><strong>${esc(x.name)}</strong><small>${esc(x._type)}</small></span></button>`).join('')}</div>`:`<p class="subtle">${esc(F('nothingYet'))}</p>`}</section>`;
}
function scenarioTable(row){
 const variants=[['current',row.pricing.mode,row.pricing.rate],['markup30','markup','30'],['markup50','markup','50'],['margin30','margin','30']];
 const rows=variants.map(([key,mode,rate])=>{try{const candidate=clone(row);candidate.pricing={...candidate.pricing,mode,rate,profitEnabled:false};const candidateDB={...db,products:db.products.map(p=>p.id===row.id?candidate:p)};const result=new C.Engine(candidateDB).product(row.id);return {label:key==='current'?F('current'):key==='markup30'?'30% markup':key==='markup50'?'50% markup':'30% margin',price:money(result.sale),profit:money(result.profit),active:key==='current'};}catch{return null;}}).filter(Boolean);
 return `<section class="scenario-panel"><div class="section-title"><div><h3>${esc(F('scenarioTitle'))}</h3><p class="hint">${esc(F('scenarioHint'))}</p></div></div><div class="scenario-grid">${rows.map(x=>`<div class="scenario ${x.active?'active':''}"><span>${esc(x.label)}</span><strong>${esc(x.price)}</strong><small>${esc(T('Прибыль'))}: ${esc(x.profit)}</small></div>`).join('')}</div></section>`;
}
function shareOrDownload(blob,name,title,text){return(async()=>{try{if(navigator.share&&typeof File==='function'){const file=new File([blob],name,{type:blob.type});if(!navigator.canShare||navigator.canShare({files:[file]})){await navigator.share({files:[file],title,text});toast(F('shared'));return;}}await download(blob,name);toast(F('sharedFallback'));}catch(e){if(e?.name!=='AbortError')await download(blob,name);}})();}
function shoppingPDF(row){const lines=engine.flatten(row).map(l=>`${l.material.name} — ${number(l.qty,6)} ${unit(l.unit)} · ${number(l.packages,0)} ${F('packages')}`);return CakePDF.create(row.name,[{heading:F('shoppingList'),lines:lines.length?lines:[F('nothingYet')]},{heading:T('Примечание'),lines:[T('Количество упаковок округлено вверх для закупки. Себестоимость учитывает только израсходованную долю упаковки.')]}]);}
function shareProductPDF(){if(!selected||invalid){toast(T('Сначала исправьте некорректные поля.'));return;}const row=entities().find(r=>r.id===selected);if(!row||route==='materials')return;const lines=[T.l`Название: ${row.name}`,T.l`Выход: ${number(row.outputQty)} ${unit(row.outputUnit)}`];if(route==='products'){const r=engine.product(row.id);lines.push(T.l`Себестоимость: ${money(r.full)}`,T.l`Рекомендуемая цена: ${money(r.sale)}`,T.l`Прибыль: ${money(r.profit)}`);}else{const r=engine.recipe(row.id);lines.push(T.l`Себестоимость партии: ${money(r.cost)}`);}shareOrDownload(CakePDF.create(row.name,[{heading:T('Основные сведения'),lines},{heading:F('shoppingList'),lines:engine.flatten(row).map(l=>`${l.material.name} — ${number(l.qty,6)} ${unit(l.unit)}`)}]),`ArgonCakeCalc-${row.id.slice(0,12)}.pdf`,row.name,F('sharePdf'));}
function shareShoppingList(){if(!selected||invalid){toast(T('Сначала исправьте некорректные поля.'));return;}const row=entities().find(r=>r.id===selected);if(!row||route==='materials')return;shareOrDownload(shoppingPDF(row),`ArgonCakeCalc-shopping-${row.id.slice(0,12)}.pdf`,F('shoppingList'),F('downloadList'));}
function render(){
 $('#route-title').textContent=routes[route][0];$('#route-note').textContent=routes[route][1];document.querySelectorAll('[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===route));app.setAttribute('aria-busy','false');
 if(route==='settings'){renderSettings();return;}
 if(route==='overview'){renderDashboard();return;}
 const records=entities();if(!records.some(r=>r.id===selected)){selected=records[0]?.id||null;draft=selected?clone(records[0]):null;}
 const intro=route==='materials'&&firstRun()?onboardingCard():'';
 app.innerHTML=T.l`${intro}<div class="toolbar"><p>${records.length} ${route==='materials'?T("материалов"):route==='recipes'?T("рецептов"):T("изделий")} · автоматический пересчёт и сохранение</p><div class="actions">${route==='costs'?'':`<button class="button" data-action="new">+ ${route==='materials'?T("Новый материал"):route==='recipes'?T("Новый рецепт"):T("Новое изделие")}</button>`}<button class="button secondary" data-action="backup">JSON-копия</button></div></div><div class="split"><aside class="card list-panel" aria-label="Список записей"><label class="sr-only" for="search">Поиск по названию</label><input id="search" type="search" placeholder="Поиск по названию…" value="${esc(query)}">${route==='materials'?T.l`<label class="sr-only" for="category-filter">Категория</label><select id="category-filter">${options([['',T("Все категории")],...db.categories.map(c=>[c,c])],categoryFilter)}</select>`:''}<div class="list-count" id="list-count"></div><div id="entity-list" class="list"></div><button class="link" data-action="more" id="load-more" hidden>Показать ещё 50</button></aside><section id="detail" class="detail"></section></div>`;
 renderList();renderDetail();enhanceHints();
}
function renderList(){const list=$('#entity-list');if(!list)return;const rows=entities().filter(r=>r.name.toLowerCase().includes(query.toLowerCase())&&(!categoryFilter||r.category===categoryFilter));$('#list-count').textContent=T.l`Найдено: ${rows.length}`;list.innerHTML=rows.slice(0,limit).map(r=>{let sub='';try{if(route==='materials'){const a=engine.material(r.id);sub=`${money(r.price)} / ${number(r.packQty)} ${unit(r.unit)}`;}else if(route==='recipes'){const a=engine.recipe(r.id);sub=`${number(a.net)} ${unit(r.outputUnit)} · ${money(a.cost)}`;}else{sub=money(engine.product(r.id).full);}}catch{}return`<button class="list-item ${r.id===selected?'selected':''}" data-select="${esc(r.id)}" aria-pressed="${r.id===selected}"><strong>${esc(r.name)}</strong><small>${esc(sub)}</small></button>`;}).join('')||T("<p class=\"subtle\">Ничего не найдено.</p>");$('#load-more').hidden=rows.length<=limit;}
function renderDetail(){const box=$('#detail');if(!box)return;if(!selected||!draft){box.innerHTML=`<div class="card empty"><div class="empty-icon" aria-hidden="true">+</div><h2>${route==='materials'?T("Начните с ваших материалов"):route==='recipes'?T("Сохраните первый рецепт"):T("Создайте своё изделие")}</h2><p>${route==='materials'?T("Укажите цену упаковки — ArgonCakeCalc рассчитает стоимость каждого грамма, миллилитра или штуки."):route==='recipes'?T("Добавьте материалы или другие рецепты. Цена вложенных компонентов обновится автоматически."):T("Соберите состав, укажите выход и настройте цену продажи.")}</p><div class="actions" style="justify-content:center"><button class="button" data-action="${route==='costs'?'open-products':'new'}">${route==='costs'?T("Открыть конструктор"):T("Добавить запись")}</button>${!db.materials.length&&!db.recipes.length&&!db.products.length?T("<button class=\"button secondary\" data-action=\"demo\">Посмотреть учебный пример</button>"):''}</div></div>`;return;}
 const isMaterial=route==='materials',isRecipe=route==='recipes',isCosts=route==='costs';
 box.innerHTML=T.l`<article class="card"><div class="detail-header"><div><span class="badge">${isMaterial?T("Материал"):isRecipe?T("Рецепт"):isCosts?T("Калькуляция"):T("Изделие")}</span><h2 style="margin-top:8px">${esc(draft.name)}</h2></div><div class="actions">${!isMaterial?T("<button class=\"button secondary\" data-action=\"pdf\">Скачать PDF</button>"):''}${!isMaterial?`<button class="button secondary" data-action="share-pdf">${esc(F('sharePdf'))}</button><button class="button secondary" data-action="share-shopping">${esc(F('shoppingList'))}</button>`:''}<button class="button secondary" data-action="clone">${!isMaterial&&!isRecipe?T("По шаблону"):T("Дублировать")}</button><button class="button danger" data-action="delete">Удалить</button></div></div><div id="edit-error" class="error" role="alert" hidden></div>
 ${isMaterial?materialForm():isCosts?pricingForm():recipeProductForm(isRecipe)}<div id="live"></div></article>`;
 updateLive();enhanceHints();}

// Every editable field gets visible, programmatically associated guidance.
function fieldHint(el){
 const path=el.dataset.field||'';
 const hints={"name":()=>T("Название записи для поиска, списков и PDF."),"category":()=>T("Категория группирует записи; на расчёт цены не влияет."),"price":()=>T("Цена всей закупочной упаковки. Пустое поле означает 0; отрицательные цены не допускаются."),"packQty":()=>T("Сколько материала в одной упаковке. Нужно положительное число."),"unit":()=>T("Единица количества в упаковке, например кг, мл или штуки."),"priceUpdated":()=>T("Дата цены: ГГГГ-ММ-ДД. Кнопка рядом открывает календарь; изменение цены обновляет дату."),"description":()=>T("Необязательная заметка. Не влияет на расчёты."),"outputQty":()=>T("Выход одной партии в выбранной единице. Сам по себе не меняет количества компонентов."),"outputUnit":()=>T("Единица выхода партии. Штуки не переводятся в массу; для перевода объёма в массу нужна плотность."),"portions":()=>T("Целое число порций, не меньше 1. Используется для себестоимости одной порции."),"loss":()=>T("Доля потерь от исходного выхода рецепта. Состав и стоимость партии не уменьшаются."),"instructions":()=>T("Текст технологии попадёт в PDF. Сам по себе не меняет расчёты."),"cake.shape":()=>T("Круглая форма использует диаметр, квадратная — длину стороны."),"cake.targetCount":()=>T("План числа ярусов: 1–14. Применяется кнопкой подбора, не добавляет ярусы сразу."),"cake.height":()=>T("Высота каждого яруса при подборе. Текущие размеры в таблице пока не меняются."),"cake.margin":()=>T("Горизонтальная ступенька между ярусами с каждой стороны. Разница диаметров равна двум отступам."),"cake.density":()=>T("Средняя масса 1 см³ торта. Умножается на объём; больше плотность — больше оценка массы."),"cake.layers":()=>T("Информационное число коржей. Не меняет состав, массу или ярусы автоматически."),"pricing.mode":()=>T("Наценка считается от себестоимости; маржинальность — от цены продажи."),"pricing.rate":()=>T("Процент выбранного способа. Пустое поле означает 0. Это не фиксированная денежная сумма."),"pricing.labor.amount":()=>T("Расход за всё изделие, не за час или порцию. Пустое поле означает 0; учитывается только с включённым флажком."),"pricing.energy.amount":()=>T("Расход за всё изделие, не за час или порцию. Пустое поле означает 0; учитывается только с включённым флажком."),"pricing.other.amount":()=>T("Расход за всё изделие, не за час или порцию. Пустое поле означает 0; учитывается только с включённым флажком."),"pricing.labor.enabled":()=>T("Флажок включает этот расход. Выключение сохраняет сумму, но исключает её из расчёта."),"pricing.energy.enabled":()=>T("Флажок включает этот расход. Выключение сохраняет сумму, но исключает её из расчёта."),"pricing.other.enabled":()=>T("Флажок включает этот расход. Выключение сохраняет сумму, но исключает её из расчёта."),"settings.currency":()=>T("Валюта всей базы. Меняется обозначение, а не суммы по обменному курсу."),"settings.locale":()=>T("Формат отображения чисел и денег: разделители и порядок символов. Не меняет язык интерфейса.")};
 if(hints[path])return hints[path]();
 if(/^components\.\d+\.qty$/.test(path))return T("Расход компонента на одну партию. Нужно число больше 0.");
 if(/^components\.\d+\.unit$/.test(path))return T("Единица расхода этой строки; она должна быть совместима с источником.");
 if(/^components\.\d+\.role$/.test(path))return T("Описывает роль компонента. Само назначение не меняет цену или количество.");
 if(/^components\.\d+\.scaling$/.test(path))return T("Выберите, как менять эту строку при масштабировании; подробности ниже.");
 if(/^cake\.tiers\.\d+\.size$/.test(path))return T("Диаметр или сторона этого яруса, см.");
 if(/^cake\.tiers\.\d+\.height$/.test(path))return T("Высота этого яруса, см.");
 if(el.dataset.source!==undefined)return T("Выберите закупочный материал или сохранённый рецепт для этой строки.");
 if(path==='pricing.lossEnabled')return T('Включает денежный резерв потерь, не меняя расход материалов.');
 if(path==='pricing.profitEnabled')return T('Включает минимальную прибыль как нижнюю границу цены.');
 const ids={'scale-target':()=>T("Новая величина выхода для команды масштабирования. Требуется положительное число; состав изменится только после нажатия кнопки."),'scale-diameter':()=>T("Новый размер нижнего яруса: диаметр или сторона. Кнопка пересчитает состав и все ярусы по коэффициенту объёма."),'scale-height':()=>T("Новая высота нижнего яруса. Используется вместе с новым диаметром или стороной для пересчёта состава."),'quote-qty':()=>T("Показывает стоимость выбранного количества рецепта. Не меняет сам рецепт."),'search':()=>T("Фильтрует список по названию. Не изменяет сохранённые записи."),'category-filter':()=>T("Показывает только материалы выбранной категории."),'new-category':()=>T("Введите название и нажмите «Добавить». Цены и состав не изменятся."),'language-select':()=>T("Язык надписей и календаря. Смена языка перезагрузит страницу, но не переведёт ваши записи.")};
 return ids[el.id]?.()||'';
}
let hintSequence=0;
function enhanceHints(){
 for(const el of document.querySelectorAll('input:not([type="file"]),select,textarea')){
  if(el.dataset.hintReady)continue;
  const label=el.closest('label'),existing=label?.querySelector(':scope > small'),text=fieldHint(el);
  if(!text&&!existing)continue;
  const ids=[];
  if(existing){existing.id||=`field-hint-${++hintSequence}`;ids.push(existing.id);}
  if(text&&existing?.textContent!==text){
   const hint=document.createElement('small');hint.className='hint field-help';hint.id=`field-hint-${++hintSequence}`;hint.textContent=text;
   if(el.id==='new-category')el.closest('.inline-form').after(hint);
   else if(el.closest('.date-control'))el.closest('.date-control').append(hint);
   else if(el.closest('.check'))el.closest('.check').after(hint);
   else el.after(hint);
   ids.push(hint.id);
  }
  el.setAttribute('aria-describedby',ids.join(' '));el.dataset.hintReady='true';
 }
}
// Keep empty input editable during typing; show its committed numeric zero on blur.
app.addEventListener('focusout',event=>{const el=event.target;if(el.value?.trim()!=='')return;if(el.id==='quote-qty'){el.value='0';return;}if(el.dataset.field&&draft&&getPath(draft,el.dataset.field)==='0')el.value='0';});
const helpTopics={
 fit:{title:()=>T('Подобрать под выход изделия'),paragraphs:()=>[T("Подбор берёт текущий выход изделия и переводит его в граммы. По плану ярусов, высоте, отступу, форме и средней плотности вычисляются размеры ярусов. Сохраняются выход, состав и стоимость материалов. Например: 2000 г при 0,5 г/см³ требуют объёма 4000 см³. Если объём слишком мал для заданных ступенек, уменьшите отступ, высоту или число ярусов. Это оценка размеров, не расчёт устойчивости.")]},
 weight:{title:()=>T('Взять выход из геометрии'),paragraphs:()=>[T("Масса силуэта = сумма объёмов ярусов × средняя плотность. Круг: π × (диаметр / 2)² × высота; квадрат: сторона² × высота. Кнопка заменяет только выход изделия. Количества ингредиентов и полная себестоимость не меняются, но себестоимость 1 кг изменится. Чтобы менять расход, используйте явное масштабирование состава, а не только замену выхода. При выходе в мл нужна плотность готового продукта; выход в штуках нельзя получить из массы.")]},
 pricing:{title:()=>T('Цена и дополнительные расходы'),paragraphs:()=>[T("Полная себестоимость = материалы + включённый резерв потерь + включённые дополнительные расходы. Суммы работы, производства и других расходов относятся ко всему изделию. Очистка суммы означает 0 и не мешает другим полям. Например: 245 + 10 = 255; после очистки снова 245. Отрицательные значения остаются ошибкой. Выключенный флажок исключает расход, не стирая сумму."),T("При себестоимости 100 и наценке 25% цена равна 125. При маржинальности 25% цена равна 100 / 0,75 и округляется вверх до 133,34. Минимальная прибыль задаёт нижнюю границу цены: себестоимость + желаемая прибыль. Резерв потерь относится только к материалам; не дублируйте потери рецептов. Изменение валюты не конвертирует суммы.")]},
 scaling:{title:()=>T('Масштабирование'),paragraphs:()=>[T("Сначала дублируйте вариант, если хотите сохранить исходный. «Применить по выходу» меняет компоненты по их правилам: пропорционально, по поверхности, фиксированно или с округлением штук вверх. Меняются сохранённые количества; проверяйте коробки и декор. Простое редактирование выхода или команда «Взять выход из геометрии» не масштабируют состав.")]}
};
function helpButton(topic){return `<button type="button" class="button secondary help-button" data-help="${topic}" aria-label="${esc(T('Подробнее')+': '+helpTopics[topic].title())}">?</button>`;}
const helpDialog=document.createElement('dialog');helpDialog.className='help-dialog';helpDialog.setAttribute('aria-labelledby','help-dialog-title');document.body.append(helpDialog);
document.addEventListener('click',event=>{const trigger=event.target.closest('[data-help]');if(trigger){const topic=helpTopics[trigger.dataset.help];if(!topic)return;helpDialog.innerHTML=`<header><h2 id="help-dialog-title" tabindex="-1">${esc(topic.title())}</h2><button type="button" class="icon-button" data-close-help aria-label="${esc(T('Закрыть справку'))}">×</button></header>${topic.paragraphs().map(p=>`<p>${esc(p)}</p>`).join('')}<button type="button" class="button secondary full" data-close-help>${esc(T('Закрыть справку'))}</button>`;helpDialog.showModal();helpDialog.querySelector('h2').focus();}if(event.target.closest('[data-close-help]'))helpDialog.close();});

function materialForm(){const m=draft;return`<div class="fields">${field(T("Название"),'name',m.name)}${select(T("Категория"),'category',m.category,db.categories.map(c=>[c,c]))}${field(T("Цена закупочной упаковки"),'price',m.price,{decimal:true,hint:T.l`Валюта: ${db.settings.currency}. Нулевая цена разрешена.`})}${field(T("Количество в упаковке"),'packQty',m.packQty,{decimal:true})}${select(T("Единица упаковки"),'unit',m.unit,Object.entries(C.UNITS).map(([k,v])=>[k,v.label]))}${field(T("Дата изменения цены"),'priceUpdated',m.priceUpdated,{type:'date'})}${field(T("Плотность, г/мл · необязательно"),'density',m.density,{decimal:true,hint:T("Нужна только для перевода массы в объём и обратно. Штуки не конвертируются.")})}${field(T("Описание / поставщик"),'description',m.description,{type:'textarea'})}</div>`;}
function recipeProductForm(isRecipe){const r=draft;return T.l`<div class="fields">${field(T("Название"),'name',r.name)}${!isRecipe?field(T("Категория изделия"),'category',r.category):field(T("Потери при приготовлении, %"),'loss',r.loss,{decimal:true,hint:T("Выход после потерь = исходный выход × (1 − потери / 100).")})}${field(isRecipe?T("Выход до технологических потерь"):T("Итоговый выход готового изделия"),'outputQty',r.outputQty,{decimal:true})}${select(T("Единица выхода"),'outputUnit',r.outputUnit,Object.entries(C.UNITS).map(([k,v])=>[k,v.label]))}${!isRecipe?field(T("Количество порций"),'portions',r.portions,{decimal:true}):''}${field(T("Плотность готового продукта, г/мл · необязательно"),'density',r.density,{decimal:true,hint:T("Для конвертации выхода из массы в объём. Не заменяет плотности ингредиентов.")})}${field(T("Описание"),'description',r.description,{type:'textarea',wide:true})}</div>
 <section class="section"><h2>Состав</h2><p class="hint">Выбирайте ваши материалы и рецепты. Количества относятся к одной партии.</p>${componentsForm()}<button class="button secondary" data-action="add-component">+ Добавить компонент</button><details><summary>Как работают правила масштабирования</summary><p>«Пропорционально» меняет количество на общий коэффициент. «По поверхности» — по площади покрытия; при изменении веса используется коэффициент в степени 2/3. «Не менять» подходит для коробки и фиксированного декора. «Округлить ↑» округляет результат масштабирования до целого. Все результаты можно поправить вручную.</p></details></section>
 <section class="section"><div class="help-heading"><h2>Масштабирование</h2>${helpButton("scaling")}</div><p class="hint">Меняет сохранённый состав. Текущий вариант можно предварительно дублировать. Изменение поля выхода выше само по себе не меняет состав.</p><div class="scale-bar"><label>Новый выход, ${esc(unit(r.outputUnit))}<input id="scale-target" inputmode="decimal" value="${esc(r.outputQty)}"></label><div class="hint">Правила применяются отдельно к каждой строке. ${isRecipe?T("Процент потерь сохраняется."):T("Число порций округляется вверх; геометрия масштабируется равномерно.")}</div><button class="button secondary" data-action="scale-weight">Применить по выходу</button></div></section>
 ${!isRecipe?geometryForm():''}
 <section class="section"><h2>Технологическая инструкция</h2>${field(T("Приготовление, сборка и примечания"),'instructions',r.instructions,{type:'textarea'})}</section>
 ${!isRecipe?pricingForm():''}`;}
function sourceOptions(current){return T.l`<option value="">Выберите компонент</option><optgroup label="Материалы">${db.materials.map(m=>`<option value="material:${esc(m.id)}" ${current===`material:${m.id}`?'selected':''}>${esc(m.name)}</option>`).join('')}</optgroup><optgroup label="Рецепты">${db.recipes.filter(r=>r.id!==selected).map(r=>`<option value="recipe:${esc(r.id)}" ${current===`recipe:${r.id}`?'selected':''}>${esc(r.name)}</option>`).join('')}</optgroup>`;}
function componentsForm(){if(!draft.components.length)return T("<p class=\"notice\">Состав пока пуст. Добавьте первый компонент.</p>");return T.l`<div class="table-wrap"><table class="components"><caption class="sr-only">Компоненты и правила масштабирования</caption><thead><tr><th>Компонент</th><th>Количество</th><th>Ед.</th><th>Назначение</th><th>Масштабирование</th><th>Стоимость</th><th></th></tr></thead><tbody>${draft.components.map((c,i)=>T.l`<tr><td class="source" data-label="${esc(T("Компонент"))}"><select aria-label="Компонент ${i+1}" data-source="${i}">${sourceOptions(c.type+':'+c.ref)}</select></td><td class="quantity" data-label="${esc(T("Количество"))}"><input aria-label="Количество компонента ${i+1}" inputmode="decimal" data-field="components.${i}.qty" value="${esc(c.qty)}"></td><td class="unit" data-label="${esc(T("Ед."))}"><select aria-label="Единица компонента ${i+1}" data-field="components.${i}.unit">${options(Object.entries(C.UNITS).map(([k,v])=>[k,v.label]),c.unit)}</select></td><td class="role" data-label="${esc(T("Назначение"))}"><select aria-label="Назначение компонента ${i+1}" data-field="components.${i}.role">${options(Object.entries(C.ROLES),c.role)}</select></td><td class="rule" data-label="${esc(T("Масштабирование"))}"><select aria-label="Правило компонента ${i+1}" data-field="components.${i}.scaling">${options(Object.entries(C.SCALING),c.scaling)}</select></td><td data-label="${esc(T("Стоимость"))}"><span class="cost-value" data-line-cost="${i}">—</span></td><td class="row-remove"><button class="icon-button" aria-label="Удалить компонент ${i+1}" data-remove-component="${i}">×</button></td></tr>`).join('')}</tbody></table></div>`;}
function geometryForm(){const g=draft.cake;return T.l`<section class="section"><h2>Размерный конструктор торта</h2><p class="hint">Геометрия и рецептура связаны только по явной команде. Изменение силуэта не подменяет выход рецепта или количества ингредиентов.</p><div class="fields three">${select(T("Форма"),'cake.shape',g.shape,[['round',T("Круглая")],['square',T("Квадратная")]])}${field(T("Количество ярусов для подбора"),'cake.targetCount',g.targetCount??g.count,{decimal:true})}${field(T("Высота яруса для подбора, см"),'cake.height',g.height,{decimal:true})}${field(T("Отступ с каждой стороны, см"),'cake.margin',g.margin,{decimal:true})}${field(T("Средняя плотность торта, г/см³"),'cake.density',g.density,{decimal:true})}${field(T("Количество коржей в изделии"),'cake.layers',g.layers,{decimal:true})}</div><div class="geometry-actions"><div class="action-guide"><div class="actions"><button class="button secondary" data-action="geometry-fit">Подобрать под выход изделия</button>${helpButton("fit")}</div><p class="hint">Размеры под существующий выход; расход компонентов не меняется.</p></div><div class="action-guide"><div class="actions"><button class="button secondary" data-action="geometry-weight">Взять выход из геометрии</button>${helpButton("weight")}</div><p class="hint">Заменяет выход оценкой массы силуэта; расход компонентов не меняется.</p></div></div><div class="geometry-layout"><div><div class="table-wrap"><table class="tier-table"><thead><tr><th>Снизу ↑</th><th id="tier-dimension">${g.shape==='round'?T("Диаметр"):T("Сторона")}, см</th><th>Высота, см</th></tr></thead><tbody>${g.tiers.map((t,i)=>T.l`<tr><td>${i+1}</td><td><input aria-label="Размер яруса ${i+1}" data-field="cake.tiers.${i}.size" inputmode="decimal" value="${esc(t.size)}"></td><td><input aria-label="Высота яруса ${i+1}" data-field="cake.tiers.${i}.height" inputmode="decimal" value="${esc(t.height)}"></td></tr>`).join('')}</tbody></table></div><p id="geometry-numbers" class="hint"></p></div><div id="cake-drawing" class="cake-svg"></div></div><div class="scale-bar"><label>Новый нижний диаметр, см<input id="scale-diameter" inputmode="decimal" value="${esc(g.tiers[0].size)}"></label><label>Новая высота нижнего яруса, см<input id="scale-height" inputmode="decimal" value="${esc(g.tiers[0].height)}"></label><button class="button secondary" data-action="scale-diameter">Пересчитать состав</button></div><p class="hint">Для круглой формы: коэффициент объёма = (новый диаметр / старый)² × (новая высота / старая). Все ярусы меняются в той же пропорции. Подставки и устойчивость не рассчитываются.</p></section>`;}
function pricingForm(){const p=draft.pricing;return T.l`<section class="section"><div class="help-heading"><h2>Цена и дополнительные расходы</h2>${helpButton("pricing")}</div><div class="fields">${select(T("Способ расчёта"),'pricing.mode',p.mode,[['markup',T("Наценка на себестоимость")],['margin',T("Целевая маржинальность")]])}${field(T("Процент наценки / маржинальности"),'pricing.rate',p.rate,{decimal:true,hint:T("Маржинальность должна быть меньше 100%.")})}</div><div class="pricing-extras" style="margin-top:20px">${[['labor',T("Работа")],['energy',T("Электроэнергия и производство")],['other',T("Другие расходы")]].map(([key,label])=>`<div class="extra">${check(label,`pricing.${key}.enabled`,p[key].enabled)}${field(T.l`Сумма, ${db.settings.currency}`,`pricing.${key}.amount`,p[key].amount,{decimal:true})}</div>`).join('')}<div class="extra">${check(T("Резерв на дополнительные потери"),'pricing.lossEnabled',p.lossEnabled)}${field(T("Потери, %"),'pricing.loss',p.loss,{decimal:true,hint:T("Резерв к материальным затратам: сумма / (1 − потери). Не включайте повторно потери, учтённые в рецептах.")})}</div><div class="extra">${check(T("Минимальная желаемая прибыль"),'pricing.profitEnabled',p.profitEnabled)}${field(T.l`Минимум прибыли, ${db.settings.currency}`,'pricing.desiredProfit',p.desiredProfit,{decimal:true,hint:T("Цена будет не ниже полной себестоимости плюс эта сумма.")})}</div></div></section>`;}
function updateLive(){const live=$('#live');if(!live||!selected)return;const row=entities().find(r=>r.id===selected);if(!row)return;
 if(route==='materials'){const m=engine.material(row.id);let extra='';if(row.density){extra=T.l`Плотность: ${number(row.density)} г/мл.`;}live.innerHTML=T.l`<section class="section"><h2>Стоимость единицы</h2><div class="metrics">${metric(`1 ${unit(m.base)}`,money(m.unitCost),T("Цена округлена только для отображения."),true)}${metric(T("Цена упаковки"),money(row.price),`${number(row.packQty)} ${unit(row.unit)}`)}${metric(T("Точная цена за единицу"),number(m.unitCost,8),`${db.settings.currency} / ${unit(m.base)}`)}</div><p class="hint">${esc(extra)} Цена используется во всех зависимых рецептах и изделиях. Промежуточные вычисления не округляются до копеек.</p></section>`;enhanceHints();return;}
 row.components.forEach((c,i)=>{const el=document.querySelector(`[data-line-cost="${i}"]`);if(el)el.textContent=money(engine.lineCost(c));});
 if(route==='recipes'){const r=engine.recipe(row.id);live.innerHTML=T.l`<section class="section"><h2>Калькуляция рецепта</h2><div class="metrics">${metric(T("Себестоимость партии"),money(r.cost),T("Все исходные компоненты."),true)}${metric(T("Выход после потерь"),`${number(r.net)} ${unit(row.outputUnit)}`)}${metric(T.l`Цена за 1 ${unit(row.outputUnit)}`,number(r.unitCost,8),db.settings.currency)}</div><div class="fields">${T.l`<label>Рассчитать стоимость количества, ${esc(unit(row.outputUnit))}<input id="quote-qty" inputmode="decimal" value="${esc(r.net.toString())}"></label><div><span class="hint">Стоимость указанного количества</span><strong id="quote-cost">${esc(money(r.cost))}</strong></div>`}</div></section>${procurement(row)}`;}
 else{const r=engine.product(row.id);const groups=new Map();for(const leaf of engine.flatten(row))groups.set(leaf.material.category,(groups.get(leaf.material.category)||D(0)).add(leaf.cost));live.innerHTML=T.l`<section class="section"><h2>Итоговая калькуляция</h2><div class="metrics">${metric(T("Рекомендуемая цена"),money(r.sale),T("За всё изделие."),true)}${metric(T("Полная себестоимость"),money(r.full))}${metric(T("Прибыль"),money(r.profit))}</div><div class="price-grid">${[[T("Материальные затраты"),money(r.material)],[T("Резерв на потери"),money(r.loss)],[T("Включённые дополнительные расходы"),money(r.extras)],[T("Фактическая наценка"),r.markup===null?'—':number(r.markup,2)+'%'],[T("Фактическая маржинальность"),r.margin===null?'—':number(r.margin,2)+'%'],[T("Себестоимость 1 кг"),money(r.perKg)],[T("Себестоимость 1 порции"),money(r.perPortion)]].map(([l,v])=>`<div class="price-row"><span>${esc(l)}</span><strong>${esc(v)}</strong></div>`).join('')}</div>${scenarioTable(row)}${r.perKg===null?T("<p class=\"hint\">Цена за килограмм недоступна: выход задан в объёме без плотности или в штуках.</p>"):''}<h3 style="margin-top:24px">Материальные затраты по категориям</h3><div class="price-grid">${[...groups].map(([l,v])=>`<div class="price-row"><span>${esc(l)}</span><strong>${esc(money(v))}</strong></div>`).join('')||T("<p class=\"hint\">Добавьте состав изделия.</p>")}</div><details><summary>Формулы цены и прибыли</summary><p>Наценка: себестоимость × (1 + процент / 100). Маржинальность: себестоимость / (1 − процент / 100). Прибыль = цена − полная себестоимость. Желаемая прибыль задаёт нижний порог цены. Налоги и комиссии отдельно не моделируются — их можно учесть в дополнительных расходах.</p></details></section>${procurement(row)}`;drawGeometry(row);}
 enhanceHints();
}
function procurement(row){const leaves=engine.flatten(row);return T.l`<section class="section"><h2>Развёрнутый расход материалов</h2><p class="hint">Вложенные рецепты раскрыты до закупочных материалов, повторяющиеся позиции объединены. Это расход, не складской учёт. Резерв дополнительных потерь изделия показан отдельно в деньгах и не включён в эту ведомость.</p>${leaves.length?T.l`<div class="table-wrap"><table class="procurement"><thead><tr><th>Материал</th><th>Расход</th><th>Масса / объём</th><th>Стоимость расхода</th><th>Упаковок ↑</th></tr></thead><tbody>${leaves.map(l=>`<tr><td class="name" data-label="${esc(T("Материал"))}">${esc(l.material.name)}<br><span class="hint">${esc(l.material.category)}</span></td><td data-label="${esc(T("Расход"))}">${number(l.qty,6)} ${esc(unit(l.unit))}</td><td data-label="${esc(T("Масса / объём"))}">${l.mass!==null?number(l.mass,3)+T(" г"):'—'} / ${l.volume!==null?number(l.volume,3)+T(" мл"):'—'}</td><td data-label="${esc(T("Стоимость расхода"))}">${esc(money(l.cost))}</td><td data-label="${esc(T("Упаковок ↑"))}">${number(l.packages,0)}</td></tr>`).join('')}</tbody></table></div><p class="hint">Число упаковок округлено вверх для закупки с нуля. Себестоимость учитывает только израсходованную долю упаковки. Объём из массы вычисляется только при заданной плотности материала.</p>`:T("<p class=\"notice\">В составе пока нет материалов.</p>")}</section>`;}
function drawGeometry(row){const box=$('#cake-drawing');if(!box||!row.cake)return;const g=row.cake,tiers=g.tiers,heights=tiers.map(t=>Number(t.height)),max=Math.max(...tiers.map(t=>Number(t.size))),total=heights.reduce((a,b)=>a+b,0),w=360,h=300,k=Math.min(258/max,220/total),cx=155,base=253;let y=base;let s=`<line x1="20" y1="${base+2}" x2="${w-22}" y2="${base+2}" class="guide"/>`;
 tiers.forEach((t,i)=>{const tw=Number(t.size)*k,th=Number(t.height)*k;y-=th;s+=T.l`<rect class="tier-shape" x="${cx-tw/2}" y="${y}" width="${tw}" height="${th}"><title>Ярус ${i+1}: ${esc(t.size)} × ${esc(t.height)} см</title></rect>`;if(th>20&&tw>28)s+=`<text class="dim tier-label" x="${cx}" y="${y+th/2+5}" text-anchor="middle">${i+1}</text>`;});s+=T.l`<text class="dim" x="${cx}" y="285" text-anchor="middle">${g.shape==='round'?T("Ø макс."):T("Сторона макс.")} ${number(max)} см</text><text class="dim" transform="translate(345 ${(base+y)/2}) rotate(-90)" text-anchor="middle">${number(total)} см всего</text>`;box.innerHTML=T.l`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Размерный силуэт. Единый масштаб осей.">${s}</svg>`;
 const mass=CakeModel.totals(tiers.map(t=>({size:Number(t.size),height:Number(t.height)})),g.shape,Number(g.density),150).grams;$('#geometry-numbers').textContent=T.l`${tiers.length} ярусов · ориентировочно ${number(D(String(mass.toFixed(6))).div(1000))} кг по геометрии. Выход изделия: ${number(row.outputQty)} ${unit(row.outputUnit)}.`;
 if(tiers.slice(1).some((t,i)=>Number(t.size)>Number(tiers[i].size)))$('#geometry-numbers').textContent+=T(" Внимание: верхний ярус шире нижнего, проверьте опоры.");
}
function renderSettings(){app.innerHTML=T.l`<div class="settings-grid"><section class="card"><h2>Валюта и формат чисел</h2><div class="fields">${select(T("Валюта"),'settings.currency',db.settings.currency,CakeI18n.currencyOptions())}${select(T("Формат чисел"),'settings.locale',db.settings.locale,CakeI18n.numberOptions())}</div><p class="warning">Смена валюты меняет обозначение, но не пересчитывает цены по курсу. Все суммы базы должны быть в одной валюте.</p><h3>Язык интерфейса</h3><p class="hint">Выберите язык вверху страницы. Язык не меняет названия ваших записей, цены или валюту сохранённой базы.</p></section>
 <section class="card"><h2>Резервное копирование</h2><p class="subtle">Экспорт включает все материалы, категории, рецепты, изделия и настройки. JSON можно перенести в другой браузер или на другое устройство.</p><div class="actions"><button class="button" data-action="backup">Скачать JSON-копию</button><button class="button secondary" data-action="import">Восстановить из JSON</button></div><p class="hint">Импорт полностью заменяет базу после проверки и подтверждения. Перед заменой текущая база автоматически выгружается в JSON.</p><p class="hint">Версия формата: 2 · ${db.materials.length} материалов / ${db.recipes.length} рецептов / ${db.products.length} изделий.</p><button class="link" data-action="recover">Восстановить предыдущее сохранение</button></section>
 <section class="card"><h2>Категории материалов</h2><p class="hint">Используемые категории нельзя удалить. Категории изделий вводятся свободным текстом.</p><div class="category-list">${db.categories.map((c,i)=>T.l`<span class="category-tag">${esc(c)}<button aria-label="Удалить категорию ${esc(c)}" data-delete-category="${i}">×</button></span>`).join('')}</div><div class="inline-form"><input id="new-category" aria-label="Название новой категории" placeholder="Например, орехи"><button class="button secondary" data-action="add-category">Добавить</button></div></section>
 <section class="card"><h2>Надёжность хранения</h2><p class="subtle">IndexedDB принадлежит этому браузеру и адресу сайта. Очистка данных сайта, приватный режим, смена адреса или устройства могут сделать базу недоступной. У приложения нет доступа к вашим файлам для фонового резервного копирования.</p><button class="button secondary" data-action="persist-storage">Запросить защиту от автоочистки</button><p id="storage-info" class="hint">Проверяем состояние хранилища…</p><p class="hint">Даже постоянное хранилище не заменяет скачанный JSON. После изменения сайта используйте прежний домен и протокол, чтобы сохранить доступ к базе.</p></section>
 <section class="card wide"><h2>Автономность и ограничения</h2><ul class="help-list"><li>Все расчёты, PDF и JSON выполняются на вашем устройстве. Нет аналитики, авторизации или внешних API.</li><li>На HTTPS-хостинге после загрузки всех ресурсов приложение доступно без интернета. Дождитесь статуса готовности офлайн.</li><li>Локальный HTML запускается без сети сразу; IndexedDB для file:// зависит от браузера. Для постоянной работы надёжнее неизменный HTTPS-адрес.</li><li>При работе в нескольких вкладках конфликт записи блокируется. Экспортируйте незаписанные изменения и перезагрузите вкладку.</li><li>Потери рецепта уменьшают выход, а не увеличивают массу закупленных ингредиентов. Не учитывайте одни и те же потери дважды.</li><li>Геометрия — приближение. Нет расчёта устойчивости, налогов, складских остатков и валютных курсов.</li><li>Лицензия: ArgonCakeCalc Commercial Source-Available License 1.0. Автор: Ivan Voitkov, 2026. Сохраните уведомления об авторстве и лицензии. Лицензии шрифтов находятся в исходниках.</li></ul><div class="actions"><button class="button secondary" data-action="demo">Добавить учебный пример</button><button class="button danger" data-action="clear">Удалить всю базу</button></div></section></div>`;storageInfo();enhanceHints();}
async function storageInfo(){const el=$('#storage-info');if(!el)return;try{const persistent=await navigator.storage?.persisted?.(),e=await navigator.storage?.estimate?.();el.textContent=T.l`Защита от автоочистки: ${persistent?T("разрешена"):T("не предоставлена")}.${e?T(" Использовано примерно ")+number(D(String(Math.round((e.usage||0)/1024))))+T(" КБ."):''}`;}catch{el.textContent=T("Браузер не предоставляет сведения о хранилище.");}}
function addEntityKey(key){if(!leaveDraft())return;const row=key==='materials'?C.newMaterial(db.categories[0]):key==='recipes'?C.newRecipe():C.newProduct();db[key].unshift(row);markFirstRun();if(route!==key){route=key;location.hash=key;}selected=row.id;draft=clone(row);engine=new C.Engine(db);invalid=false;persist();render();setTimeout(()=>document.querySelector('[data-field="name"]')?.focus(),0);}
function addEntity(){addEntityKey(tableName());}
function duplicate(){if(!leaveDraft())return;const row=clone(entities().find(r=>r.id===selected));row.id=C.uid();row.name+=T(" — копия");if(row.components)row.components.forEach(c=>c.id=C.uid());db[tableName()].unshift(row);selected=row.id;draft=clone(row);invalid=false;engine=new C.Engine(db);persist();render();toast(T("Создан независимый вариант. Ссылки на материалы и рецепты сохранены."));}
function addComponent(){if(invalid){toast(T("Сначала исправьте некорректные поля."));return;}const sources=[...db.materials.map(m=>({type:'material',ref:m.id,unit:m.unit})),...db.recipes.filter(r=>r.id!==selected).map(r=>({type:'recipe',ref:r.id,unit:r.outputUnit}))];if(!sources.length){toast(T("Сначала добавьте хотя бы один материал или другой рецепт."));return;}for(const src of sources){const line={id:C.uid(),...src,qty:'1',role:'ingredient',scaling:'proportional'};const candidate=clone(draft);candidate.components.push(line);try{C.validateDB({...db,[tableName()]:entities().map(r=>r.id===selected?candidate:r)});draft=candidate;acceptDraft({render:true});return;}catch{}}toast(T("Нет доступного компонента без циклической зависимости. Добавьте материал."));}
function sample(){markFirstRun();if(!confirm(T("Добавить учебный набор с условными ценами? Ваши данные сохранятся. Это пример, не реальные закупочные цены.")))return;const defs=[[T("Мука пшеничная"),T("Ингредиенты"),'90','1','kg',''],[T("Сахар"),T("Ингредиенты"),'100','1','kg',''],[T("Сливки 33%"),T("Ингредиенты"),'500','1','l','1.01'],[T("Шоколад"),T("Ингредиенты"),'1200','1','kg',''],[T("Коробка для торта"),T("Упаковка"),'120','1','pcs',''],[T("Яйцо"),T("Ингредиенты"),'120','10','pcs','']];for(const name of [T("Ингредиенты"),T("Упаковка")])if(!db.categories.includes(name))db.categories.push(name);const m=defs.map(([name,category,price,packQty,unit,density])=>({...C.newMaterial(),name,category,price,packQty,unit,density}));const line=(src,qty,unit,role='ingredient',scaling='proportional')=>({id:C.uid(),type:'material',ref:src.id,qty,unit,role,scaling});const sponge={...C.newRecipe(),name:T("Учебный бисквит"),outputQty:'900',loss:'10',instructions:T("Пример: взбить яйца с сахаром, вмешать муку и выпечь. Уточните технологию под свою рецептуру."),components:[line(m[0],'300','g'),line(m[1],'250','g'),line(m[5],'5','pcs')]};const cream={...C.newRecipe(),name:T("Учебный шоколадный крем"),outputQty:'950',loss:'0',components:[line(m[2],'600','ml'),line(m[3],'300','g')]};const p={...C.newProduct(),name:T("Шоколадный торт · учебный"),outputQty:'1800',portions:'12',instructions:T("Пример сборки: три коржа, два слоя крема, выравнивание и упаковка."),components:[{id:C.uid(),type:'recipe',ref:sponge.id,qty:'810',unit:'g',role:'cake',scaling:'proportional'},{id:C.uid(),type:'recipe',ref:cream.id,qty:'950',unit:'g',role:'cream',scaling:'proportional'},line(m[4],'1','pcs','packaging','fixed')]};p.pricing.labor={enabled:true,amount:'500'};const candidate={...db,materials:[...m,...db.materials],recipes:[sponge,cream,...db.recipes],products:[p,...db.products]};engine=new C.Engine(candidate);db=candidate;persist();selected=null;draft=null;invalid=false;render();toast(T("Учебный набор добавлен. Все цены условные."));}
function exportPDF(){const money=v=>v===null?'—':new Intl.NumberFormat(db.settings.locale,{minimumFractionDigits:2,maximumFractionDigits:2}).format(D(v).round(2).toString())+' '+db.settings.currency;if(invalid){toast(T("Сначала исправьте некорректные поля. PDF формируется по последним сохранённым данным."));return;}const row=entities().find(r=>r.id===selected),isRecipe=route==='recipes';const sections=[{heading:T("Основные сведения"),lines:[T.l`Название: ${row.name}`,T.l`Выход: ${number(isRecipe?C.netOutput(row):row.outputQty)} ${unit(row.outputUnit)}`,isRecipe?T.l`Потери: ${number(row.loss)}%`:T.l`Порций: ${row.portions}`,T.l`Валюта: ${db.settings.currency} · ${new Date().toLocaleDateString(db.settings.locale)}`,row.description||'']},{heading:T("Состав партии"),lines:row.components.map(c=>T.l`${engine.source(c).name} — ${number(c.qty,6)} ${unit(c.unit)}; ${C.ROLES[c.role]}; стоимость ${money(engine.lineCost(c))}`)},{heading:T("Расход исходных материалов с раскрытием рецептов"),lines:engine.flatten(row).map(l=>T.l`${l.material.name}: ${number(l.qty,6)} ${unit(l.unit)}; ${money(l.cost)}; упаковок для закупки: ${number(l.packages,0)}. Масса: ${l.mass===null?T("не определена"):number(l.mass)+T(" г")}, объём: ${l.volume===null?T("не определён"):number(l.volume)+T(" мл")}.`)}];
 if(isRecipe){const r=engine.recipe(row.id);sections.push({heading:T("Себестоимость рецепта"),lines:[T.l`Себестоимость партии: ${money(r.cost)}`,T.l`Стоимость 1 ${unit(row.outputUnit)}: ${number(r.unitCost,8)} ${db.settings.currency}`]});}else{const r=engine.product(row.id);sections.push({heading:T("Калькуляция изделия"),lines:[T.l`Материальные затраты: ${money(r.material)}`,T.l`Резерв дополнительных потерь: ${money(r.loss)}`,...['labor','energy','other'].map((k,i)=>`${[T("Работа"),T("Электроэнергия и производство"),T("Другие расходы")][i]}: ${row.pricing[k].enabled?money(row.pricing[k].amount):T("не включено")}`),T.l`Полная себестоимость: ${money(r.full)}`,T.l`Метод: ${row.pricing.mode==='markup'?T("наценка"):T("целевая маржинальность")} ${number(row.pricing.rate)}%`,T.l`Рекомендуемая цена продажи: ${money(r.sale)}`,T.l`Прибыль: ${money(r.profit)}`,T.l`Наценка: ${r.markup===null?T("не определена"):number(r.markup,2)+'%'}`,T.l`Маржинальность: ${r.margin===null?T("не определена"):number(r.margin,2)+'%'}`,T.l`Себестоимость 1 кг: ${money(r.perKg)}`,T.l`Себестоимость 1 порции: ${money(r.perPortion)}`]});sections.push({heading:T("Геометрия торта"),lines:[T.l`Форма: ${row.cake.shape==='round'?T("круглая"):T("квадратная")}. Коржей в изделии: ${row.cake.layers}.`,...row.cake.tiers.map((t,i)=>T.l`Ярус ${i+1} снизу: ${row.cake.shape==='round'?T("диаметр"):T("сторона")} ${number(t.size)} см, высота ${number(t.height)} см.`)]});}
 sections.push({heading:T("Технологическая инструкция"),lines:[row.instructions||T("Не указана.")]},{heading:T("Примечание"),lines:[T("Калькуляция основана на введённых пользователем данных. Запас дополнительных потерь изделия не включён в количественную ведомость. Устойчивость конструкции, налоги и комиссии отдельно не рассчитываются.")]});
 try{download(CakePDF.create(row.name,sections),`CakeCalc-${isRecipe?'recipe':'product'}-${row.id.replace(/[^a-zA-Z0-9_-]/g,'').slice(0,16)}.pdf`);}catch(e){globalError(T("Не удалось создать PDF: ")+e.message);}
}
async function importFile(file){try{if(!file)return;if(file.size>20*1024*1024)throw Error(T("Максимальный размер копии — 20 МБ."));const candidate=C.migrate(JSON.parse(await file.text()));new C.Engine(candidate);if(!confirm(T.l`Заменить всю базу? В копии: ${candidate.materials.length} материалов, ${candidate.recipes.length} рецептов, ${candidate.products.length} изделий. Текущая база будет автоматически скачана перед заменой.`))return;backup(true);await store.flush();db=candidate;engine=new C.Engine(db);markFirstRun();selected=null;draft=null;invalid=false;persist();render();globalError('');toast(T("Копия проверена и восстановлена."));}catch(e){globalError(T("Импорт не выполнен. Текущая база сохранена. ")+e.message);}finally{$('#import-file').value='';}}
async function action(name){try{switch(name){case'new':addEntity();break;case'new-material':addEntityKey('materials');break;case'new-recipe':addEntityKey('recipes');break;case'new-product':addEntityKey('products');break;case'open-products':navigate('products');break;case'share-pdf':shareProductPDF();break;case'share-shopping':shareShoppingList();break;case'backup':backup();break;case'import':$('#import-file').click();break;case'clone':duplicate();break;case'demo':if(leaveDraft())sample();break;case'more':limit+=50;renderList();break;case'pdf':exportPDF();break;case'add-component':addComponent();break;
 case'delete':{const key=tableName(),used=key==='products'?[]:C.referencedBy(db,key==='materials'?'material':'recipe',selected);if(used.length){toast(T("Удаление запрещено. Используется в: ")+used.slice(0,6).join(', '));return;}if(!confirm(T.l`Удалить «${draft.name}»? Отменить можно восстановлением предыдущего сохранения или JSON-копии.`))return;db[key]=db[key].filter(r=>r.id!==selected);selected=null;draft=null;invalid=false;engine=new C.Engine(db);persist();render();break;}
 case'scale-weight':case'scale-diameter':{if(invalid)throw Error(T("Исправьте некорректные поля перед масштабированием."));const spec=name==='scale-weight'?{mode:'weight',target:$('#scale-target').value.replace(',','.')}: {mode:'diameter',diameter:$('#scale-diameter').value.replace(',','.'),height:$('#scale-height').value.replace(',','.')};const next=C.scaleEntity(draft,spec);const old=draft;draft=next;if(!acceptDraft({render:true})){const error=$('#edit-error').textContent;draft=old;invalid=false;renderDetail();toast(error);}else toast(T("Состав масштабирован. Проверьте фиксированные компоненты и округление штук."));break;}
 case'geometry-fit':{if(invalid)throw Error(T("Сначала исправьте некорректные поля."));const g=draft.cake,grams=C.convert(draft.outputQty,draft.outputUnit,'g',draft.density);g.tiers=CakeModel.solve({grams:grams.toNumber(),count:g.targetCount??g.count,height:Number(g.height),margin:Number(g.margin),density:Number(g.density),shape:g.shape}).map(t=>({size:String(t.size),height:String(t.height)}));g.count=g.tiers.length;acceptDraft({render:true});break;}
 case'geometry-weight':{if(invalid)throw Error(T("Сначала исправьте некорректные поля."));const g=draft.cake,total=CakeModel.totals(g.tiers.map(t=>({size:Number(t.size),height:Number(t.height)})),g.shape,Number(g.density),150).grams;draft.outputQty=C.convert(D(total.toFixed(9)),'g',draft.outputUnit,draft.density).round(6).toString();acceptDraft({render:true});toast(T("Выход взят из геометрии. Количества ингредиентов не менялись."));break;}
 case'add-category':{const name=$('#new-category').value.trim();if(!name||name.length>200)throw Error(T("Укажите название категории до 200 символов."));if(db.categories.includes(name))throw Error(T("Такая категория уже существует."));db.categories.push(name);persist();renderSettings();break;}
 case'persist-storage':{const yes=await navigator.storage?.persist?.();toast(yes?T("Браузер разрешил постоянное хранение. JSON-копии всё равно необходимы."):T("Браузер не предоставил постоянное хранение. Регулярно скачивайте JSON."));await storageInfo();break;}
 case'recover':{const old=await store.get('previous');if(!old)throw Error(T("Предыдущее сохранение отсутствует."));const restored=C.migrate(old.data);if(!confirm(T("Восстановить предыдущее успешное сохранение? Текущая база сначала будет скачана в JSON. Это один шаг, не история версий.")))return;backup(true);await store.flush();db=restored;engine=new C.Engine(db);persist();render();toast(T("Предыдущее сохранение восстановлено."));break;}
 case'clear':{if(!confirm(T("Удалить все материалы, рецепты, изделия и настройки? Текущая база сначала будет выгружена в JSON.")))return;backup(true);await store.flush();db=C.emptyDB();engine=new C.Engine(db);persist();selected=null;draft=null;invalid=false;render();toast(T("База очищена."));break;}
 }}catch(e){toast(e.message);}}
// Event delegation: ordinary field changes only update computed views, never recreate focused inputs.
document.addEventListener('click',e=>{const actionEl=e.target.closest('[data-action]');if(actionEl){action(actionEl.dataset.action);return;}const nav=e.target.closest('[data-route]');if(nav){navigate(nav.dataset.route);return;}const item=e.target.closest('[data-select]');if(item){if(!leaveDraft())return;selected=item.dataset.select;draft=clone(entities().find(r=>r.id===selected));invalid=false;renderList();renderDetail();return;}const remove=e.target.closest('[data-remove-component]');if(remove){if(invalid){toast(T("Сначала исправьте некорректные поля."));return;}if(!confirm(T("Удалить эту строку состава?")))return;draft.components.splice(Number(remove.dataset.removeComponent),1);acceptDraft({render:true});return;}const cat=e.target.closest('[data-delete-category]');if(cat){const name=db.categories[Number(cat.dataset.deleteCategory)];if(db.materials.some(m=>m.category===name)){toast(T("Категория используется материалами. Сначала перенесите их в другую категорию."));return;}if(db.categories.length===1){toast(T("Нельзя удалить последнюю категорию."));return;}if(confirm(T.l`Удалить категорию «${name}»?`)){db.categories=db.categories.filter(c=>c!==name);persist();renderSettings();}}});
app.addEventListener('input',e=>{
 const el=e.target;if(el.id==='search'){query=el.value;limit=50;renderList();return;}
 if(el.id==='quote-qty'){try{const r=engine.recipe(selected),q=C.amount(el.value.trim().replace(',','.')||'0',T("Количество"),'0');$('#quote-cost').textContent=money(r.unitCost.mul(q));}catch{$('#quote-cost').textContent=T("Введите количество не меньше нуля.");}return;}
 if(!el.dataset.field||el.tagName==='SELECT'||el.type==='checkbox')return;editField(el);
});
app.addEventListener('change',e=>{const el=e.target;if(el.id==='category-filter'){categoryFilter=el.value;renderList();return;}if(el.dataset.source!==undefined){const [type,ref]=el.value.split(':'),source=(type==='material'?db.materials:db.recipes).find(r=>r.id===ref);if(!source)return;const i=Number(el.dataset.source);const old=clone(draft);draft.components[i]={...draft.components[i],type,ref,unit:type==='material'?source.unit:source.outputUnit};if(!acceptDraft({render:true})){const error=$('#edit-error').textContent;draft=old;invalid=false;renderDetail();toast(error);}return;}if(el.dataset.field&&(el.tagName==='SELECT'||el.type==='checkbox'))editField(el);});
function editField(el){const path=el.dataset.field;if(route==='settings'){const candidate=clone(db);if(path==='settings.currency'&&el.value!==db.settings.currency&&!confirm(T("Изменить валюту всей базы без пересчёта сумм по курсу?"))){el.value=db.settings.currency;return;}setPath(candidate,path,el.value);try{engine=new C.Engine(candidate);db=candidate;persist();}catch(e){toast(e.message);}return;}
 const isNumber=!['name','description','instructions','category','priceUpdated'].includes(path)&&!path.endsWith('.unit')&&!path.endsWith('.role')&&!path.endsWith('.scaling')&&!['unit','outputUnit','cake.shape','pricing.mode'].includes(path);
 let value=el.type==='checkbox'?el.checked:el.value;if(isNumber&&typeof value==='string'){value=value.trim().replace(',','.');if(value===''&&path!=='density')value='0';}if(path==='cake.targetCount')value=Number(value);setPath(draft,path,value);
 if(route==='materials'&&['price','packQty','unit'].includes(path)){draft.priceUpdated=new Date().toISOString().slice(0,10);const date=document.querySelector('[data-field="priceUpdated"]');if(date)date.value=draft.priceUpdated;}
 acceptDraft();
}
$('#import-file').addEventListener('change',e=>importFile(e.target.files[0]));
window.addEventListener('beforeunload',e=>{if(invalid||storageFailed||store.busy||store.pending){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(routes[next]&&next!==route)navigate(next);});
async function offlineSetup(){const el=$('#offline-status');if(location.protocol==='file:'){el.textContent=T("Локальный файл · работает без сети");return;}if(!('serviceWorker'in navigator)){el.textContent=T("Офлайн-кеш недоступен в этом браузере");return;}try{const reg=await navigator.serviceWorker.register('./sw.js');let updating=false;const showUpdate=()=>{if(reg.waiting&&navigator.serviceWorker.controller){$('#update-banner').hidden=false;$('#apply-update').onclick=()=>{updating=true;reg.waiting?.postMessage('ACTIVATE_UPDATE');};}};showUpdate();reg.addEventListener('updatefound',()=>reg.installing?.addEventListener('statechange',showUpdate));let reloading=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(updating&&!reloading){reloading=true;location.reload();}});await navigator.serviceWorker.ready;el.textContent=T("Офлайн-ресурсы готовы");}catch{el.textContent=T("Офлайн-кеш не создан: используйте HTTPS или localhost");}}
(async()=>{try{const data=await store.open();db=data?C.migrate(data):C.emptyDB();engine=new C.Engine(db);ready=true;if(!data||data.formatVersion!==db.formatVersion)persist();const hash=location.hash.slice(1);if(routes[hash])route=hash;render();updateBackupNote();offlineSetup();if(navigator.storage?.persisted&&!await navigator.storage.persisted())$('#backup-note').textContent+=T(" Скачивайте копии регулярно.");}catch(e){globalError(T("База не открылась: ")+e.message+T(" Не очищайте данные сайта. Проверьте доступность IndexedDB и разрешения браузера."));app.innerHTML=T("<section class=\"card\"><h2>Безопасный запуск остановлен</h2><p>Чтобы не потерять данные, приложение не заменяет повреждённую базу пустой. Попробуйте обычный, не приватный режим или прежний адрес сайта. Если есть JSON-копия, откройте приложение в отдельном профиле браузера и восстановите её.</p></section>");}})();
})();
